  'Intercultural Communication',
  'This course develops students'' ability to analyze and practice communication across cultures, identities, languages, institutions, media systems, and global contexts. Students examine culture, identity, power, language, nonverbal communication, conflict, migration, diaspora, race, gender, class, religion, disability, digital platforms, global media, ethical representation, and intercultural competence through theory, cases, reflection, and applied projects.',
  $icomjson${"slug": "intercultural-communication", "title": "Intercultural Communication", "description": "This course develops students' ability to analyze and practice communication across cultures, identities, languages, institutions, media systems, and global contexts. Students examine culture, identity, power, language, nonverbal communication, conflict, migration, diaspora, race, gender, class, religion, disability, digital platforms, global media, ethical representation, and intercultural competence through theory, cases, reflection, and applied projects.", "topics": [{"id": "13f3f4a7-f0bf-4107-a985-43593d5e7453", "type": "topic", "title": "Intercultural Communication Foundations: Culture, Meaning, Context, and Competence", "description": "Students learn how culture shapes meaning-making, interaction, identity, and communicative competence.", "children": [{"id": "2ab2860f-31a0-4071-8852-d7baaf21a75e", "type": "subtopic", "title": "Culture as communication context", "children": [{"id": "846cbcfe-d580-450b-ae91-32ac3d0c4794", "type": "concept", "title": "Symbols, norms, values, practices, and institutions"}, {"id": "936fb4b0-9eb4-4d0d-8375-d8d75d9a312d", "type": "concept", "title": "Culture as dynamic, contested, and situational"}, {"id": "d2d923b4-dab1-4834-a98c-e3c02e95b2ce", "type": "concept", "title": "High-stakes consequences of misreading context"}], "description": "The point is to see culture as a lived system of meanings and practices, not a checklist of traits."}, {"id": "c19fa145-0015-4eaa-a374-72dc3322637b", "type": "subtopic", "title": "Communication competence", "children": [{"id": "634a1a08-5ea7-476d-8234-3cf5ab6e3dd9", "type": "concept", "title": "Knowledge, motivation, skills, and reflection"}, {"id": "4f76741c-e98a-42eb-a932-ac3cace48ff7", "type": "concept", "title": "Appropriateness and effectiveness"}, {"id": "fc1ac8f0-42da-4f5b-8526-cfcf82c79876", "type": "concept", "title": "Competence versus assimilation or performance"}], "description": "Students learn that competence means adapting with respect, accuracy, humility, and effectiveness."}, {"id": "93b24185-49ae-4240-a7ae-a602d91b3381", "type": "subtopic", "title": "Intercultural practice", "children": [{"id": "990fc007-aefd-4c40-8589-a556865b8ef2", "type": "concept", "title": "Curiosity, listening, reflexivity, and accountability"}, {"id": "ef956640-3c9b-4171-9fe9-01b30893d40f", "type": "concept", "title": "Careful generalization and avoidance of stereotypes"}, {"id": "707e391b-e8d2-4e37-bf8e-55e776f238d8", "type": "concept", "title": "Local context, relationship, and history"}], "description": "The course frames intercultural communication as ethical, evidence-based, and power-aware."}]}, {"id": "647b2bfc-d6c9-4d24-83b3-36043a9806af", "type": "topic", "title": "Culture, Cultural Identity, Belonging, and Positionality", "description": "This module examines how people locate themselves and others through cultural identities, histories, communities, and power.", "children": [{"id": "1857b7db-34f1-4b9c-a0c4-c5a1e33149e1", "type": "subtopic", "title": "Cultural identity", "children": [{"id": "c775860d-ce9f-4d96-9985-33635384fb07", "type": "concept", "title": "National, ethnic, racial, linguistic, religious, regional, and community identities"}, {"id": "8966f566-8ab8-412d-b351-68bdf1d11ec7", "type": "concept", "title": "Identity salience and context"}, {"id": "e5364361-83a8-450a-8cb1-c3167e7311b4", "type": "concept", "title": "Multiple, hybrid, and changing identities"}], "description": "Students learn how identities are formed, communicated, claimed, assigned, and negotiated."}, {"id": "b171ed3d-a53b-414b-8d81-c92022860e98", "type": "subtopic", "title": "Belonging and community", "children": [{"id": "526b3194-cff7-4f67-9ccc-2468200442dd", "type": "concept", "title": "In-groups, out-groups, boundary work, and belonging cues"}, {"id": "0ace245f-6d1e-4ebf-89a9-f64dfc236aa6", "type": "concept", "title": "Family, community, institutions, and media"}, {"id": "274b4393-678f-4d43-864e-7c6d4bac0709", "type": "concept", "title": "Recognition, dignity, and misrecognition"}], "description": "Communication creates boundaries of inclusion, exclusion, membership, and recognition."}, {"id": "97ef6b5b-7beb-4a70-a4df-a2380624f385", "type": "subtopic", "title": "Positionality", "children": [{"id": "897dfcb4-c72f-4763-b6d5-afa7a6b2db51", "type": "concept", "title": "Privilege, marginalization, standpoint, and social location"}, {"id": "23e27b3d-1759-4ab4-8e3a-467f3950a7a0", "type": "concept", "title": "Reflexive writing and bias awareness"}, {"id": "5772a5a7-c766-4086-ac4b-5c58e59bc061", "type": "concept", "title": "Power in observation, description, and judgment"}], "description": "Students practice identifying how their own location shapes interpretation and interaction."}]}, {"id": "291c0840-e8bb-4a3f-86fd-559aa0a0e9b5", "type": "topic", "title": "Theories and Models: Cultural Dimensions, Context, Face, and Uncertainty", "description": "Students compare classic and contemporary theories while learning their uses, limits, and risks of overgeneralization.", "children": [{"id": "8a49ab58-b4f6-485c-ae52-9117c2152b14", "type": "subtopic", "title": "Cultural dimensions", "children": [{"id": "dd97ff2d-f8b2-47ad-963a-e394fae6ae32", "type": "concept", "title": "Hofstede, Hall, Trompenaars, and GLOBE"}, {"id": "44df8547-2386-4ec4-b492-d150cd241d12", "type": "concept", "title": "Individualism, collectivism, power distance, uncertainty avoidance, and masculinity/femininity"}, {"id": "f54e4689-0e70-430c-b717-f6e5f7fa9363", "type": "concept", "title": "Limits, critiques, and ecological fallacy"}], "description": "Students use dimensions as lenses, while learning why they can never substitute for lived evidence."}, {"id": "58f537e7-6e98-4e20-a425-d5fd71a03001", "type": "subtopic", "title": "Context, face, and politeness", "children": [{"id": "a67c76be-63db-46e6-a342-d1d6ad8dc7b7", "type": "concept", "title": "High-context and low-context communication"}, {"id": "c0c4059d-a25b-4b43-af61-cd0a745ab0b9", "type": "concept", "title": "Face negotiation and facework"}, {"id": "91f433a0-990e-408a-a31f-c4b15012d33f", "type": "concept", "title": "Politeness, honorifics, status, and relational obligations"}], "description": "Students learn theories that explain indirectness, public image, relationship maintenance, and respect."}, {"id": "f6b48b87-564e-4b9e-8333-2f8e5e742db7", "type": "subtopic", "title": "Uncertainty and anxiety", "children": [{"id": "5081e85f-96c8-4c71-9c4b-412741f36ab1", "type": "concept", "title": "Uncertainty reduction and anxiety/uncertainty management"}, {"id": "6b7351d0-41f5-4d25-bf2e-b09150756e01", "type": "concept", "title": "Attribution, prediction, and sensemaking"}, {"id": "2beee04d-c2f9-4db2-9cf2-47377121dbc1", "type": "concept", "title": "Mindfulness, listening, and tolerance for ambiguity"}], "description": "The gist is to understand how unfamiliar interaction creates uncertainty and how people manage it."}]}, {"id": "59226f69-c7e3-4fa2-b8d2-5c04b2ccb357", "type": "topic", "title": "Verbal Communication, Language, Power, Translation, and Interpretation", "description": "This topic explores how language choices carry meaning, status, worldview, and access across cultural contexts.", "children": [{"id": "162f703c-2dfc-458c-8030-61d99c2f0d65", "type": "subtopic", "title": "Language and worldview", "children": [{"id": "bd28a151-2810-41a7-b2b4-534078363b08", "type": "concept", "title": "Sapir-Whorf debates, categories, metaphors, and framing"}, {"id": "3ad7734f-2c4f-463b-b598-e9427070807d", "type": "concept", "title": "Code-switching, translanguaging, dialect, and register"}, {"id": "3738382b-728a-432b-9223-76369d49d38c", "type": "concept", "title": "Language ideologies and linguistic prestige"}], "description": "Students learn how language does more than transmit information."}, {"id": "1b5790f4-d600-430f-b325-e0c85a95d548", "type": "subtopic", "title": "Power in language", "children": [{"id": "f42a0d9c-460e-4c90-9525-5001ce0b0c08", "type": "concept", "title": "Accent bias, naming, labels, and gatekeeping"}, {"id": "f92a5753-f3c7-4ad6-b7a5-6a2840d14e85", "type": "concept", "title": "Colonial language histories and linguistic imperialism"}, {"id": "495ed036-1056-411f-a345-ddf07ffa87fb", "type": "concept", "title": "Plain language, multilingual access, and language justice"}], "description": "Language can open access, mark status, or reproduce inequality."}, {"id": "37ea3a4d-1512-48c8-8c6f-14e7fb987caa", "type": "subtopic", "title": "Translation and interpretation", "children": [{"id": "4e38dab5-c8b9-4e61-9f90-8c631483ec9a", "type": "concept", "title": "Literal versus cultural translation"}, {"id": "64c25040-e824-4a3a-abbe-bd30a17c6332", "type": "concept", "title": "Interpreters, machine translation, and professional ethics"}, {"id": "863e5d2a-c0af-4afc-94dc-4237c0c18ee9", "type": "concept", "title": "Ambiguity, idioms, humor, and culturally bound concepts"}], "description": "Students learn the challenges of carrying meaning across languages and contexts."}]}, {"id": "b4a68a1f-9b8e-47a3-92ea-fca4466d5ed6", "type": "topic", "title": "Nonverbal Communication, Space, Time, Embodiment, and Relational Cues", "description": "Students learn how gestures, silence, distance, time, touch, and embodiment vary across communities and situations.", "children": [{"id": "c29ee8cb-1fd5-471c-907e-99105746fc13", "type": "subtopic", "title": "Nonverbal systems", "children": [{"id": "b2e0622e-4234-4759-9d27-73f425ad22fb", "type": "concept", "title": "Gesture, eye contact, facial display, posture, and silence"}, {"id": "d72dccab-6a16-4585-a13d-b652f228439f", "type": "concept", "title": "Touch, paralanguage, and emotional expression"}, {"id": "4a708fbb-2443-4b8b-af54-3fbd3f98a52c", "type": "concept", "title": "Avoiding universal assumptions"}], "description": "Students learn to interpret nonverbal cues carefully and contextually."}, {"id": "82a252c6-5789-4f80-8302-e1ec2d17882b", "type": "subtopic", "title": "Space and time", "children": [{"id": "c8d22809-9ac1-4127-a98b-3a32dfe6aa09", "type": "concept", "title": "Proxemics, territoriality, and public/private space"}, {"id": "50fc3619-1389-451f-b363-b49082df8b00", "type": "concept", "title": "Monochronic and polychronic time"}, {"id": "85f4b955-9883-488b-84c3-87421dd6c168", "type": "concept", "title": "Waiting, punctuality, pace, and scheduling norms"}], "description": "Cultures organize relationship, hierarchy, urgency, and respect through space and time."}, {"id": "4ba78f81-a61b-4a78-9d78-07cadf2a1124", "type": "subtopic", "title": "Embodiment and access", "children": [{"id": "4bbc2771-2480-487b-b805-0f34ba986374", "type": "concept", "title": "Disability, sensory norms, and accessibility"}, {"id": "2d3c1b1d-75a7-47e2-91d9-a45705b2ed21", "type": "concept", "title": "Gendered expectations and bodily discipline"}, {"id": "b7f99de8-468a-4676-a4d7-2ed2932f3411", "type": "concept", "title": "Embodied discomfort, safety, and consent"}], "description": "Students connect nonverbal norms to bodies, ability, gender, and social expectations."}]}, {"id": "95ff1c0d-e982-4438-9172-e48fa6c680e3", "type": "topic", "title": "Stereotypes, Prejudice, Bias, Microaggressions, and Intergroup Perception", "description": "This module teaches how bias enters communication and how reflective practice can reduce harm.", "children": [{"id": "02548d16-aade-426d-8908-f05118ff1a90", "type": "subtopic", "title": "Stereotyping and prejudice", "children": [{"id": "0f770aaa-95bb-442b-8bcf-08a463f20b2a", "type": "concept", "title": "Stereotypes, prejudice, discrimination, and essentialism"}, {"id": "dd583fcb-c97a-4b7a-bd4c-4180aed5649a", "type": "concept", "title": "Confirmation bias and attribution error"}, {"id": "dd29a25a-f7c1-4fbc-928b-78565f481765", "type": "concept", "title": "Media images and social learning"}], "description": "Students learn how simplified group images shape interaction before people speak."}, {"id": "b77983ee-a10b-4578-9ec8-095dd840700e", "type": "subtopic", "title": "Microaggressions and everyday harm", "children": [{"id": "62122f99-b4ff-49a9-81e5-8f1f4393cc6c", "type": "concept", "title": "Microinsults, microinvalidations, and coded language"}, {"id": "47a61314-a1ba-450b-98d2-b91ae3f1126d", "type": "concept", "title": "Intent versus impact"}, {"id": "4eaa3953-34b7-43cc-89f9-8d861033d93c", "type": "concept", "title": "Repair, accountability, and learning"}], "description": "The point is to recognize subtle communication patterns that accumulate harm."}, {"id": "dda4ee0b-bda9-4447-adea-16816ab46bfd", "type": "subtopic", "title": "Bias interruption", "children": [{"id": "8f87d312-7316-4423-981d-ed198d220966", "type": "concept", "title": "Perspective-taking with limits"}, {"id": "c224525c-fa4f-4a0b-b507-9a01e01420a3", "type": "concept", "title": "Bias checks and reflective pauses"}, {"id": "9b5e9fd4-4b23-47c2-ae79-34caf0a11cb0", "type": "concept", "title": "Bystander intervention and dialogue skills"}], "description": "Students practice strategies for more accurate, respectful, and accountable communication."}]}, {"id": "3214902e-f71d-4a73-b99e-91e2ea536772", "type": "topic", "title": "Intercultural Conflict, Dialogue, Negotiation, and Repair", "description": "Students learn to analyze conflict styles, facework, power, emotion, listening, and repair across differences.", "children": [{"id": "284a66fe-33fe-442a-88cd-83066879007f", "type": "subtopic", "title": "Conflict styles", "children": [{"id": "5ae573e7-d944-4570-9c4c-d4bc7306db98", "type": "concept", "title": "Direct and indirect conflict"}, {"id": "7c62ae2e-5a5c-460d-a782-e39816bedb88", "type": "concept", "title": "Avoiding, accommodating, competing, compromising, and collaborating"}, {"id": "84b466d8-3c94-400a-b3b8-fb0cd8be5289", "type": "concept", "title": "Face, honor, emotion, and relationship preservation"}], "description": "Students learn how conflict expression varies by context, relationship, and power."}, {"id": "c15e7fb5-58b2-4f83-90ae-6d4ff9ff22d5", "type": "subtopic", "title": "Dialogue and listening", "children": [{"id": "cb699814-c728-4235-a2eb-c2e9e96926ee", "type": "concept", "title": "Active listening, paraphrasing, inquiry, and acknowledgment"}, {"id": "297a96e6-f3f0-45c8-ad7a-1002939e071d", "type": "concept", "title": "Dialogue versus debate"}, {"id": "40130a59-3853-4d7f-9de5-8825905e1b73", "type": "concept", "title": "Brave spaces, safety, and facilitation norms"}], "description": "Intercultural dialogue requires humility, structure, and a willingness to stay with complexity."}, {"id": "9a114b20-90aa-42e2-9428-26669e78ac28", "type": "subtopic", "title": "Repair and negotiation", "children": [{"id": "852c47ad-65b1-4efa-894e-ac688ab68431", "type": "concept", "title": "Apology, restitution, reframing, and mediation"}, {"id": "abdafd0d-5405-4c2a-9e91-a61515b4ab9f", "type": "concept", "title": "Interest-based negotiation across cultures"}, {"id": "b047279c-5494-4658-ae13-54cba6c3fd33", "type": "concept", "title": "Power asymmetry and durable repair"}], "description": "Students learn how to move from misunderstanding to accountability and practical agreement."}]}, {"id": "8cf92b6d-94f4-4318-8836-2990ac336e98", "type": "topic", "title": "Adaptation, Acculturation, Migration, Diaspora, and Culture Shock", "description": "This topic studies intercultural transition, belonging, identity negotiation, and transnational community life.", "children": [{"id": "89d450c8-8a63-469f-afcc-772f716fda71", "type": "subtopic", "title": "Adaptation and culture shock", "children": [{"id": "8822a1bc-f799-4bf0-a61f-d72765178b79", "type": "concept", "title": "U-curve, W-curve, stress-adaptation-growth, and critique"}, {"id": "34e2118d-d2c6-41dd-9d2f-0bb9a60dcf30", "type": "concept", "title": "Homesickness, ambiguity, identity strain, and resilience"}, {"id": "a2a8530a-a0ee-439b-9122-54d6714b3534", "type": "concept", "title": "Support networks and coping strategies"}], "description": "Students study the emotional and communicative demands of entering new cultural contexts."}, {"id": "0b81f4f3-c203-4d4b-a7fa-2ea8bc2583b0", "type": "subtopic", "title": "Acculturation and identity negotiation", "children": [{"id": "480d6db9-e368-4b9e-adf5-8cecff2eccec", "type": "concept", "title": "Assimilation, separation, integration, and marginalization"}, {"id": "8b5dbfce-9639-4ea4-9099-685ba50197fc", "type": "concept", "title": "Biculturalism, hybridity, and third culture spaces"}, {"id": "8aab6c6f-6192-419a-ad9e-72b8ade02d6d", "type": "concept", "title": "Family, school, work, and community contexts"}], "description": "The gist is to examine how people maintain, blend, resist, or shift cultural practices."}, {"id": "960652da-b279-40ec-9b33-5dedcdc287fa", "type": "subtopic", "title": "Migration and diaspora", "children": [{"id": "dbc9594a-cc58-447f-ab75-d2b320520b77", "type": "concept", "title": "Diaspora communities and long-distance belonging"}, {"id": "bafaee3e-8386-4a2b-a6ed-ce8f2af92c35", "type": "concept", "title": "Refugee, immigrant, expatriate, student, and labor migration experiences"}, {"id": "281cdd17-80ec-44c3-b38e-368788b29843", "type": "concept", "title": "Media, remittances, language, and identity continuity"}], "description": "Students connect intercultural communication to movement, displacement, and transnational ties."}]}, {"id": "3b1a91df-89f2-44f6-b75f-5d4818a3fa2d", "type": "topic", "title": "Race, Gender, Class, Religion, Disability, Sexuality, and Intersectionality", "description": "Students examine how overlapping identities and institutions shape communication possibilities and constraints.", "children": [{"id": "3e932a1a-519c-41a5-ac15-6ab362da8a8e", "type": "subtopic", "title": "Intersectionality", "children": [{"id": "ba15ee0a-82fe-47ed-bfae-54e117336a84", "type": "concept", "title": "Race, gender, class, religion, disability, sexuality, nationality, and age"}, {"id": "c952827f-e296-4811-95a1-7fd68ca74788", "type": "concept", "title": "Structural power and everyday interaction"}, {"id": "8019d228-236d-40cb-9905-ed64963e5dba", "type": "concept", "title": "Intersectional listening and analysis"}], "description": "Students learn how identities and systems overlap rather than operate separately."}, {"id": "0538b341-18c0-432b-b0e7-85006ca773d2", "type": "subtopic", "title": "Institutional context", "children": [{"id": "895bc59b-2191-4d56-ae22-a31115714b72", "type": "concept", "title": "Policies, norms, access, and representation"}, {"id": "68a8fc6f-8477-43c4-b4a4-3ec6bc25f49c", "type": "concept", "title": "Discrimination, inclusion, and belonging practices"}, {"id": "c61670e6-7d54-452a-9807-35a2c90b75d4", "type": "concept", "title": "Institutional apologies, statements, and accountability"}], "description": "Communication is shaped by schools, workplaces, media, governments, and platforms."}, {"id": "65d1b6e4-75e2-46e3-bc25-b0577f3cdaec", "type": "subtopic", "title": "Identity-sensitive practice", "children": [{"id": "0d5c2952-222e-4759-8a73-82f32396d636", "type": "concept", "title": "Asking versus assuming"}, {"id": "49979073-a4d1-4140-8690-28180b954e77", "type": "concept", "title": "Consent, privacy, and disclosure"}, {"id": "c769101d-e65c-4089-a89c-ef97144bd488", "type": "concept", "title": "Pronouns, names, accessibility, and religious/cultural observances"}], "description": "Students learn to communicate with care without making people into categories."}]}, {"id": "08628195-6c33-4e35-8e09-e4283d1a5ea1", "type": "topic", "title": "Global Media, Cultural Hybridity, Representation, and Transnational Flows", "description": "This module connects intercultural communication to media systems, globalization, popular culture, and representation.", "children": [{"id": "6aefe4d8-fc20-4638-8986-f360c4b78f8b", "type": "subtopic", "title": "Global media flows", "children": [{"id": "484be8f1-d306-4d27-bff8-1f58dd08e21f", "type": "concept", "title": "Cultural imperialism, globalization, localization, and glocalization"}, {"id": "2f6369c9-4a0b-4704-81ac-76847936f73c", "type": "concept", "title": "Streaming, news, advertising, music, games, and fandoms"}, {"id": "93910e6c-c176-469a-ad12-418c2fe1c3df", "type": "concept", "title": "Media ownership, regulation, and platform power"}], "description": "Students learn how media texts, platforms, and industries cross borders."}, {"id": "0766f61b-2f94-4d2a-b859-867e92f59589", "type": "subtopic", "title": "Cultural hybridity", "children": [{"id": "26c8f8aa-ba85-42b7-a502-b155e26fe639", "type": "concept", "title": "Creolization, fusion, appropriation, and adaptation"}, {"id": "bbcfadf2-8e42-4d26-bd13-66fefb3f05f3", "type": "concept", "title": "Popular culture, fashion, food, and language mixing"}, {"id": "044db4ff-1ba5-4e0d-b1f2-a3c68511bc8a", "type": "concept", "title": "Authenticity debates and cultural ownership"}], "description": "Hybrid cultural forms show how people remix meaning across places and identities."}, {"id": "01826b3b-1c48-47a0-8c0b-0437254285eb", "type": "subtopic", "title": "Representation", "children": [{"id": "6fa680e7-bccc-4a17-ae05-889ce85cef5d", "type": "concept", "title": "Stereotypes, visibility, erasure, and counter-narratives"}, {"id": "7e910daf-e33b-4193-9364-3cb9bbc8dfee", "type": "concept", "title": "Framing, voice, and standpoint"}, {"id": "a87de2d3-2801-4ca7-b470-577f5f9fd2b1", "type": "concept", "title": "Ethical image, story, and source selection"}], "description": "Students analyze how media representations shape identity, power, and public perception."}]}, {"id": "a23e8082-6ca6-48fc-b272-c4b00bfb9930", "type": "topic", "title": "Digital Intercultural Communication, Networked Publics, Algorithms, and Misinformation", "description": "Students study intercultural interaction across platforms, online communities, creator cultures, and algorithmic environments.", "children": [{"id": "c957c977-69f6-4c13-8cb7-1b5f05f3dc73", "type": "subtopic", "title": "Networked publics", "children": [{"id": "9d122c95-1bd9-4402-aa38-0a98d644483d", "type": "concept", "title": "Online self-presentation and context collapse"}, {"id": "167bad89-f048-4dee-8021-94522e032200", "type": "concept", "title": "Diaspora networks and transnational publics"}, {"id": "aa5ace59-d376-4218-a190-669e83d7fd16", "type": "concept", "title": "Influencers, creators, and participatory culture"}], "description": "Students learn how online spaces reconfigure audience, identity, and community."}, {"id": "ece364f0-528c-4d65-ad7c-7c22f884cc8e", "type": "subtopic", "title": "Algorithms and platforms", "children": [{"id": "2d0c2b07-9c23-4a85-bba9-67c06a328238", "type": "concept", "title": "Algorithmic curation, recommendation, moderation, and shadow banning"}, {"id": "7cfd5fb1-95c9-42dd-9f9f-477de9fa397e", "type": "concept", "title": "Platform governance and content policy"}, {"id": "acc061b7-2844-4cfe-9434-8963eba9286b", "type": "concept", "title": "Data, surveillance, and privacy"}], "description": "Digital systems shape whose voices circulate and whose are suppressed."}, {"id": "e0aca9d8-14c5-422f-8cfc-9eb611c9b71e", "type": "subtopic", "title": "Misinformation and conflict", "children": [{"id": "88810594-531e-4f16-ac32-9e0b714d4bee", "type": "concept", "title": "Rumors, disinformation, propaganda, and translation gaps"}, {"id": "f2bfad61-68cd-4bd6-a85f-74a1059b364f", "type": "concept", "title": "Source verification and lateral reading"}, {"id": "7744c6f7-e451-4db8-8040-2316e97efc77", "type": "concept", "title": "Hate speech, harassment, and cross-cultural moderation"}], "description": "Students study how misinformation travels across cultural, linguistic, and political boundaries."}]}, {"id": "43eeced0-f9af-4df7-a33b-fe2accd5db35", "type": "topic", "title": "Cross-Cultural Business, Teamwork, Leadership, and Negotiation", "description": "This topic applies intercultural competence to workplaces, global teams, client work, and organizational communication.", "children": [{"id": "f9c99f5b-b3af-4986-926e-3b5d7f9cfb04", "type": "subtopic", "title": "Global teamwork", "children": [{"id": "eb7d52a8-be69-4a62-a98d-725b5f9d91d4", "type": "concept", "title": "Virtual collaboration, meeting norms, and decision-making"}, {"id": "b8a0416b-42bc-4dd7-9f74-96ac7e5246a4", "type": "concept", "title": "Psychological safety and inclusion"}, {"id": "4200f943-ee4d-46f3-a7f3-c49d759d3800", "type": "concept", "title": "Role clarity, feedback, and conflict escalation"}], "description": "Students learn how teams coordinate across language, time zone, hierarchy, and norms."}, {"id": "0da4bcfe-5223-410d-9341-bcf1bdb643a4", "type": "subtopic", "title": "Leadership and management", "children": [{"id": "e68cade7-a60c-4395-9b2e-3b5910010337", "type": "concept", "title": "Authority, participation, feedback, and accountability"}, {"id": "a1c4f1eb-56a6-4720-9447-ab818d4f8b10", "type": "concept", "title": "Motivation, trust, and relationship-building"}, {"id": "8bb1aae6-abf5-4da7-a314-08ca469437a3", "type": "concept", "title": "Inclusive leadership and cultural humility"}], "description": "Leadership expectations vary across cultures and institutions."}, {"id": "553f3209-7e99-415b-9ee5-91a59c21e6ae", "type": "subtopic", "title": "Negotiation and client communication", "children": [{"id": "16bb435e-541d-4ba2-9c06-de15534f9cb2", "type": "concept", "title": "Relationship versus task orientation"}, {"id": "5a84d6d6-98eb-40af-a7a8-3e50099744f1", "type": "concept", "title": "Directness, silence, concessions, and time horizons"}, {"id": "4dd2fea1-74f8-4817-a81a-adaa60e0657a", "type": "concept", "title": "Ethical persuasion, contracts, and mutual understanding"}], "description": "Students practice adapting negotiation strategies without stereotyping counterparts."}]}, {"id": "41eb33c3-feca-4440-b293-fb4cd9e32735", "type": "topic", "title": "Ethical Representation, Cultural Appropriation, Advocacy, and Public Communication", "description": "Students learn ethical decision-making for representing people, cultures, communities, and conflicts.", "children": [{"id": "c523975c-741b-4841-bd4f-e95bb2bfc3a9", "type": "subtopic", "title": "Ethical representation", "children": [{"id": "bfdc5f92-a6f1-4987-9727-3fb6a72d8456", "type": "concept", "title": "Voice, consent, context, and harm reduction"}, {"id": "87a31a07-f4b0-42be-876c-3204589c6565", "type": "concept", "title": "Tokenism, savior narratives, and extraction"}, {"id": "fcbfdaa6-efd3-4d01-9919-3f7a350c2737", "type": "concept", "title": "Community review and reciprocal benefit"}], "description": "Students learn to represent communities with accuracy, dignity, and accountability."}, {"id": "bb394817-f122-4909-9854-328a4cd5fd2f", "type": "subtopic", "title": "Cultural appropriation", "children": [{"id": "30fd0cb2-db8c-4508-a6d3-cb3743cba473", "type": "concept", "title": "Power, profit, attribution, sacredness, and consent"}, {"id": "9221b66f-b028-434d-ad10-ac39dc84688f", "type": "concept", "title": "Brand, media, art, fashion, and campaign cases"}, {"id": "9391296a-8d17-453c-9690-91ad1f29344e", "type": "concept", "title": "Repair, credit, and accountability"}], "description": "The point is to distinguish appreciation, exchange, borrowing, exploitation, and erasure."}, {"id": "238283b7-3743-4980-840a-dc19257d5e83", "type": "subtopic", "title": "Advocacy and public communication", "children": [{"id": "fcd500d7-3bd8-4e80-bfcc-34fbc0154f0c", "type": "concept", "title": "Human rights, public diplomacy, NGO, and community communication"}, {"id": "360f7b00-f7a1-409f-b654-3736a7bac109", "type": "concept", "title": "Strategic messaging with cultural care"}, {"id": "2b684edc-7956-4cc1-aea7-ad0bc9967c29", "type": "concept", "title": "Risk, backlash, and coalition communication"}], "description": "Students learn to communicate across difference in civic, nonprofit, organizational, and global settings."}]}, {"id": "9cd9bb64-2aab-4f6c-b376-4faba5bdf96d", "type": "topic", "title": "Intercultural Research Methods, Case Analysis, and Reflective Practice", "description": "This module prepares students to use evidence, observation, interviews, case analysis, and reflexivity responsibly.", "children": [{"id": "0e9af744-2a5b-459f-8b85-01f090bbd5b4", "type": "subtopic", "title": "Research methods", "children": [{"id": "9261bca3-689b-402a-bd23-93bc8781843d", "type": "concept", "title": "Interviewing, observation, ethnography, surveys, and discourse analysis"}, {"id": "3387b801-6ccb-41bb-a7a5-69db532a8e6c", "type": "concept", "title": "Sampling, translation, and research relationships"}, {"id": "fc33b778-d559-407c-966a-9dbee62d830a", "type": "concept", "title": "Consent, privacy, and researcher positionality"}], "description": "Students learn to gather intercultural evidence ethically and interpret it cautiously."}, {"id": "c003606c-da86-4a77-9385-22e46ec53dcd", "type": "subtopic", "title": "Case analysis", "children": [{"id": "4132f312-d372-41b4-81b8-9cf2e83ea6be", "type": "concept", "title": "Incident timelines, stakeholder maps, cultural context, and power analysis"}, {"id": "5156dee2-1e77-4105-a230-f171302733d3", "type": "concept", "title": "Competing interpretations and missing voices"}, {"id": "a1acd13d-3dea-41c9-a179-19ecb97fbf52", "type": "concept", "title": "Recommendations and implementation constraints"}], "description": "Case work helps students connect theory to real communication problems."}, {"id": "b43b6543-1fc1-44d6-93d6-b3bc1c35e1fa", "type": "subtopic", "title": "Reflective practice", "children": [{"id": "8695f889-4e3e-4625-88ac-05cfbcf3bf62", "type": "concept", "title": "Critical incident journals"}, {"id": "fda3ac2f-9c55-4f04-8b7b-fa55eacf50c4", "type": "concept", "title": "Competence self-assessment"}, {"id": "e30cd4f0-f928-42de-ad6b-7f87f2d843a5", "type": "concept", "title": "Feedback, revision, and growth plans"}], "description": "The course requires students to examine their own habits of interpretation."}]}, {"id": "6567a419-0df1-4eca-80c9-f03d04342ec8", "type": "topic", "title": "Global Communication Case Portfolio and Intercultural Competence Capstone", "description": "Students synthesize theory and practice through a polished case portfolio and competence development plan.", "children": [{"id": "51429d1e-0f9d-4bbf-9523-36714ad379e8", "type": "subtopic", "title": "Portfolio design", "children": [{"id": "4a12a1d0-26bd-4c49-8a9f-69e34c517289", "type": "concept", "title": "Case studies, memos, campaign critique, and dialogue analysis"}, {"id": "a2ac4f00-7124-442e-bfdf-85da20396c21", "type": "concept", "title": "Theory application and evidence quality"}, {"id": "25193ac3-3aa7-4b4a-9454-24e1d5011c63", "type": "concept", "title": "Professional formatting and audience awareness"}], "description": "Students assemble evidence of intercultural analysis and communication practice."}, {"id": "8adc946f-5fa6-418f-b642-422236d04858", "type": "subtopic", "title": "Competence development plan", "children": [{"id": "289d6e53-6904-4ed5-a91f-e661a4550d4f", "type": "concept", "title": "Strengths, blind spots, goals, and practice routines"}, {"id": "669b1a3f-08e0-4e2c-983a-24f50a7b7bb7", "type": "concept", "title": "Language, listening, research, and conflict skills"}, {"id": "dc929f39-b72f-4bd0-960d-745eb7265a6c", "type": "concept", "title": "Mentors, communities, and continued learning"}], "description": "Students make growth concrete rather than vague."}, {"id": "0f6753e6-0611-4a21-a163-3eb3dbd222d6", "type": "subtopic", "title": "Final presentation", "children": [{"id": "cff65fba-9ceb-490e-aae7-d1cff1d0c0de", "type": "concept", "title": "Case narrative, key evidence, ethical stakes, and recommendation"}, {"id": "a4c9ce41-0b2a-43d1-9016-20e9a43bbdfa", "type": "concept", "title": "Handling questions and disagreement"}, {"id": "5a0a9ec3-f7da-47a2-a462-1bcb9bb9353d", "type": "concept", "title": "Reflection on positionality, limitations, and next steps"}], "description": "Students practice explaining intercultural complexity clearly and responsibly."}]}], "db